    "k016": "enki.ngo · 공익 비영리 협회",
    "k017": "<b>enki.ngo</b> · 공익 비영리 협회",
    "k018": "지능은 그들의 데이터센터가 아니라 <em>당신의 기기</em> 위에 있어야 합니다.",
    "k019": "회비 없이 1인 1표를 갖는 300인의 공익 협회입니다. 우리는 선언문을 지키며, 누구나 대량 생산할 수 있는 주머니 크기의 로컬 AI 데이터센터 오픈 청사진을 설계하고, 당신의 기기들을 하나로 엮는 메시 표준을 작성합니다. 이곳에 \"공짜\"는 없습니다. 레지스트리는 오픈 모델의 실제 운영 비용을 투명하게 공개합니다.",
    "k020": "선언문 읽기",
    "k021": "기기 살펴보기",
    "k022": "<span class=\"hero-stat__value\">÷280</span> <span class=\"hero-stat__label\">GPT-3.5급 추론 비용, 2022년 11월 → 2024년 10월</span>",
    "k023": "<span class=\"hero-stat__value\">3.8B</span> <span class=\"hero-stat__label\">개의 파라미터가 2022년 540B가 하던 일을 수행</span>",
    "k024": "<span class=\"hero-stat__value\">~59%</span><span class=\"hero-stat__label\">의 PC가 2026년 AI-Advanced를 탑재해 출하</span>",
