    "md.olmo-3-7b.cons.1": "65K 컨텍스트 — 중간 수준",
    "md.ministral-3-14b.selfHost": "게시자 FP8 적합성: 24GB VRAM. 컨텍스트 및 동시성은 별도로 검증하세요.",
