    "md.ministral-3-8b.cons.0": "게시자는 FP8이 12GB VRAM에 적합하다고 설명합니다. 더 작은 형식 주장은 자체 구성이 필요합니다.",
    "md.qwen35-4b.selfHost": "최소 메모리가 검증되지 않았습니다. 멀티미디어 구성 요소, 컨텍스트 및 런타임을 고려하세요.",
    "md.qwen35-4b.pros.0": "4B 언어 파라미터; 텍스트, 이미지 및 비디오 입력. 네이티브 컨텍스트: 262,144 토큰.",
