    "md.phi-4-mini.pros.1": "MIT 라이선스",
    "md.phi-4-mini.cons.0": "기본 Flash Attention은 하드웨어 요구 사항이 있습니다. 이전 GPU는 카드의 대체 어텐션 설정을 필요로 합니다.",
