    "md.gemma-4-e4b.selfHost": "최소 메모리가 검증되지 않았습니다. E4B는 4B 총 저장 파라미터를 의미하지 않습니다.",
    "md.gemma-4-e4b.pros.0": "임베딩 포함 8B 파라미터; 유효 4.5B. 텍스트, 이미지 및 오디오 입력; 128K 컨텍스트.",
    "md.gemma-4-e4b.pros.1": "엣지에서의 네이티브 함수 호출",
    "md.gemma-4-e4b.pros.2": "128K 컨텍스트",
    "md.gemma-4-e4b.cons.0": "카드는 오디오를 30초, 비디오를 초당 1프레임으로 60초로 제한합니다.",
    "md.gemma-4-e4b.cons.1": "커스텀 라이선스, OSI 승인 아님",
