    "md.llama-32-3b.selfHost": "게시자 OnePlus 12 BF16 예제: 7,419MB RSS, 보편적인 최소값은 아닙니다.",
    "md.llama-32-3b.pros.0": "전체 정밀도 제품군에서 128K 컨텍스트를 가진 3.21B 텍스트 모델.",
    "md.llama-32-3b.pros.1": "MacBook Air에서 초당 30토큰 이상",
    "md.llama-32-3b.pros.2": "거대한 파인튜닝 생태계",
    "md.llama-32-3b.cons.0": "사용자 정의 라이선스 및 허용 가능한 사용 약관이 적용되며, 출처 표시 및 대규모 플랫폼 라이선스 조건이 포함됩니다.",
