    "md.llama-32-1b.selfHost": "게시자 OnePlus 12 BF16 예제: 3,185MB RSS; 양자화된 배포는 다릅니다.",
    "md.llama-32-1b.pros.0": "1.23B 텍스트 모델. 전체 정밀도 컨텍스트는 128K이며, 나열된 양자화된 텍스트 모델은 8K를 사용합니다.",
