    "md.llama-32-1b.cons.0": "사용자 정의 라이선스, 허용 가능한 사용 및 출처 표시 약관이 적용됩니다. 기본 또는 명령어 튜닝 체크포인트가 필요한지 확인하세요.",
    "md.ministral-3-3b.selfHost": "게시자 FP8 적합성: 8GB VRAM. 3B 레이블에서 총 메모리를 추론하지 마십시오.",
    "md.ministral-3-3b.pros.0": "0.4B 비전 인코더를 포함한 3.4B 언어 파라미터; 256K 컨텍스트.",
