    "md.smollm3-3b.selfHost": "최소 메모리가 검증되지 않았습니다. 런타임 지원은 Transformers 4.53.0부터 시작합니다.",
    "md.smollm3-3b.pros.0": "64K 컨텍스트로 학습된 3B 텍스트 모델; 카드는 YaRN을 사용하여 128K로의 확장을 설명합니다.",
