    "md.minimax-m25.selfHost": "최소 메모리가 검증되지 않았습니다. 모델 이름은 배포 사양이 아닙니다.",
    "md.minimax-m25.pros.0": "모델 카드는 229B 파라미터와 텍스트 생성을 나열합니다.",
    "md.minimax-m25.pros.1": "라이트닝 어텐션은 205K 창을 빠르게 유지합니다",
    "md.minimax-m25.pros.2": "100 tok/s로 자체 호스팅 시 시간당 약 1달러",
    "md.minimax-m25.cons.0": "수정된 MIT는 MIT와 동일하지 않습니다. 라이선스 파일을 검토하세요. 예제 로드에는 사용자 정의 코드가 필요합니다.",
    "md.minimax-m25.cons.1": "텍스트 전용 — 비전 레인 없음",
    "md.qwen38-flash-next.selfHost": "180B 나열된 총계이며, 6B 메모리 풋프린트가 아닙니다. 최소 하드웨어는 검증되지 않았습니다.",
    "md.qwen38-flash-next.pros.0": "카드는 125B 언어 파라미터, 51B n-그램 임베딩 및 4B MTP 파라미터를 나열하며, 6B가 활성화됩니다.",
