    "md.qwen38-flash-next.pros.2": "오픈 체크포인트에서 SWE-bench Pro 62.5",
    "md.qwen38-flash-next.cons.0": "262,144 토큰 네이티브 컨텍스트; 1M으로 확장하려면 구성이 필요합니다. 커뮤니티 약관을 검토해야 합니다.",
    "md.qwen38-flash-next.cons.1": "n-gram 테이블은 양자화되어도 실제 메모리를 원합니다",
    "md.nemotron-3-super.selfHost": "FP8의 게시자 최소 사양: 2xH100 80GB; 1개의 B200/B300도 설명되어 있습니다.",
    "md.nemotron-3-super.pros.0": "개요에 120B 총계 및 12B 활성. 텍스트 입력 및 출력; 최대 1M 컨텍스트.",
    "md.nemotron-3-super.pros.1": "가중치, 데이터셋 및 훈련 레시피 모두 공개",
    "md.nemotron-3-super.pros.2": "할인 호스트는 $0.10부터 서비스 제공",
    "md.nemotron-3-super.cons.0": "연결된 FP8 카드는 서버 하드웨어를 지정합니다. NVIDIA의 모델 라이선스 및 NIM 컨테이너 약관은 별개입니다.",
    "md.nemotron-3-super.cons.1": "NVIDIA 오픈 라이선스 — 재배포 전에 읽기",
    "md.gpt-oss-120b.selfHost": "게시자 목표: 지원되는 MXFP4 구현이 있는 80GB GPU 1개.",
    "md.gpt-oss-120b.pros.0": "총 117B, 활성 5.1B. 게시자는 MXFP4 MoE 가중치를 사용하여 80GB GPU 1개에서 작동한다고 설명합니다.",
    "md.gpt-oss-120b.pros.1": "MXFP4 네이티브로 제공: 80GB 카드 하나로 실행 가능",
    "md.gpt-oss-120b.pros.2": "방대한 서비스 생태계를 갖춘 Apache-2.0",
    "md.gpt-oss-120b.cons.0": "Harmony 형식이 필요합니다. 적합성을 주장하기 전에 컨텍스트, 동시성 및 런타임을 확인하세요.",
    "md.gpt-oss-120b.cons.1": "비전 입력 없음",
    "md.intern-s1.selfHost": "서버 규모 배포. 실행 전에 사용자 정의 모델 코드를 검토해야 합니다.",
    "md.intern-s1.pros.0": "총 241B: 235B 언어 모델 및 6B 비전 인코더. 텍스트, 이미지 및 비디오 입력.",
    "md.intern-s1.pros.1": "클린 Apache-2.0 하의 멀티모달 추론",
