    "md.step-37-flash.cons.0": "llama.cpp 섹션은 최소 120GB 통합 메모리/VRAM을 지정하고 128GB를 권장합니다.",
    "md.step-37-flash.cons.1": "Qwen/GLM 거인보다 작은 생태계",
    "md.jais-70b.selfHost": "이 체크포인트에 대한 최소 메모리가 검증되지 않았습니다.",
    "md.jais-70b.pros.0": "연결된 Jais-adapted-70B 체크포인트는 4,096 토큰 컨텍스트를 가진 70B 텍스트 모델입니다.",
