    "k1167": "{{svg1}}<span>간단히 말해서</span>",
    "k1168": "{{svg1}}<span><b>가입 신청 →</b></span>",
    "k1169": "Enki: 로컬 우선 AI를 위한 창립 이니셔티브. 제안된 300명의 회원, 좌석당 한 표.",
