    "svg90.e538bcde86a7": "호환 앱",
    "svg90.9282e57fd95b": "04 · 중립적 보관 — 공급업체 중립적 사양 · 개방형 레지스트리 · 필요한 경우 입법",
    "a90.feb291463481@aria-label": "제안된 Enki 표준: 서명된 모델 업데이트가 지원 기기의 로컬 메시로 유입되어 게이트웨이를 통해 호환 클라이언트에 제공되며, 중립적 관리 하에 있습니다",
    "meta90.45f3beaff6f7@content": "ENKI-1은 채택되거나 구현된 프로토콜이 아닌 제안된 로컬 AI 메시 표준입니다. 등록, 모델 업데이트, 게이트웨이 및 거버넌스 요구 사항을 읽어보십시오.",
