    "apply90.12b664700f": "이 브라우저에서는 녹음이 지원되지 않습니다. 대신 입력하거나 첨부하십시오.",
    "apply90.a73ad84be9": "해당 녹음 파일이 너무 큽니다. 더 짧은 메모를 녹음하거나, 예시를 입력하거나, 파일을 첨부하십시오.",
