    "apply90.9cb8f515a1": "계속하려면 한 가지 분야를 선택하십시오. 나머지는 3단계에서 언급할 수 있습니다.",
    "apply90.75a28759ca": "최소한 하나의 칩을 탭하십시오. 또는 다른 것을 이름 지정하십시오.",
