    "apply90.e2ace3c625": "링크 하나만 제공하십시오 — LinkedIn, GitHub, 논문, 보도 자료… 어디든 귀하의 작업이 실제로 작동하는 것을 볼 수 있는 곳.",
    "apply90.152ecad115": "해당 링크가 URL처럼 보이지 않습니다. linkedin.com/in/you와 같은 것이 작동합니다.",
