    "apply.yourVoice": "음성 메모",
    "apply90.a89491addd": "이것은 미리보기입니다. 여기서 신청서를 제출할 수 없습니다. 실제 신청은 enki.ngo에서 진행하며, 답변은 이 페이지에 유지됩니다.",
    "apply90.c6c9be6f56": "서약에 체크하세요. 이것이 전체 계약입니다.",
    "apply90.e11adeb687": "첨부 파일이 너무 커서 함께 보낼 수 없습니다. 하나를 제거하거나 공개 포트폴리오 링크를 사용하세요. 답변은 그대로 유지됩니다.",
