    "md.deepseek-v41-flash.link.0": "게시자 증거",
    "md.sep.13.t": "중형 체크포인트",
    "md.sep.13.n": "14B ~ 70B개 이상 나열된 파라미터. 양자화 및 런타임을 지정해야 합니다.",
    "md.sep.31.t": "소형 체크포인트",
    "md.sep.31.n": "4B ~ 14B개 이상 나열된 파라미터. 메모리는 가중치 파일보다 많습니다.",
    "md.sep.43.t": "소형 체크포인트",
    "md.sep.43.n": "소형 체크포인트. 각 카드에서 전체 모델 크기와 메모리 요구 사항을 확인하세요. 휴대폰 호환성은 여전히 기기 수준 테스트가 필요합니다.",
    "simple94.lede": "엔키는 대기업에서 빌려 쓰기만 하는 것이 아니라, 여러분이 직접 소유하고 통제할 수 있는 유용한 일상용 인공지능을 만들려는 프로젝트입니다.",
    "simple94.sections.0.h": "당신의 AI, 당신의 규칙",
    "simple94.sections.0.p.0": "엔키는 매일 여러분을 돕는 AI가 멀리 있는 데이터센터에서만이 아니라, 여러분이 가진 기기에서 돌아가야 한다고 믿습니다. 그러려면 저렴한 AI 칩과 오픈 소프트웨어가 필요하고, 그래야 개인 AI가 여러분의 필요에 맞게 일하면서 프라이버시도 지킬 수 있습니다.",
    "simple94.sections.0.p.1": "최전선 AI에는 막대한 컴퓨팅 자원이 필요할 수 있습니다. 위험한 역량에는 엄격한 감독이 필요합니다. 엔키는 두 개의 분리된 영역을 제안합니다. 하나는 최전선 연구와 데이터센터 집약형 AI이고, 다른 하나는 여러분이 통제하는 기기 위의 일상 AI입니다. 진전이 검증되고 비용이 내려가면, 유용한 도구가 첫 번째 영역에서 두 번째 영역으로 단계적으로 옮겨 갈 수 있습니다. 이 생각이 프로젝트의 모든 부분을 이끕니다.",
    "simple94.sections.1.h": "당신의 기기들을 위한 공통 언어",
    "simple94.sections.1.p.0": "프로토콜은 지원되는 기기들이 함께 일할 수 있게 해 주는, 제안된 공통 언어입니다. 또 하나의 AI 모델이 아니라 규칙의 모음입니다. 예를 들어 휴대폰이 PC에 작업을 도와 달라고 요청할 수 있습니다.",
    "simple94.sections.1.p.1": "앞으로는 적합한 프로세서를 갖춘 스마트 온수기나 태양광 게이트웨이 같은 다른 기기도 이 로컬 네트워크에 참여할 수 있겠지만, 반드시 여러분이 분명히 허락한 경우에만 가능합니다. 그런 기기는 언제나 본래의 역할을 먼저 하고, 전력과 열의 한도를 지키며, 이런 작업을 안전 제어 기능과 분리해 둘 것입니다.",
    "simple94.sections.1.link": "프로토콜 보기",
    "simple94.sections.2.h": "당신이 대화하는 앱",
    "simple94.sections.2.p.0": "클라이언트는 여러분이 AI와 대화할 때 쓰는 앱, 즉 소프트웨어입니다. 엔키의 목표는 이 인터페이스를 실제로 일을 하는 AI 모델과 분리하는 것입니다. 그러면 특정 회사의 클라우드 서비스에 묶이지 않고 마음에 드는 앱을 자유롭게 고를 수 있습니다.",
    "simple94.sections.2.p.1": "제안된 Context Vault(컨텍스트 볼트)는 여러분의 선호와 대화 기록을 여러분의 하드웨어에 보관할 것입니다. 그래서 앱을 바꿔도 처음부터 다시 시작하지 않아도 됩니다. 각 앱이 어떤 정보에 접근할 수 있는지, 그리고 클라우드 서비스와 공유할 것이 있다면 무엇을 공유할지는 여러분이 정합니다. 클라우드 서비스로 보낸 정보는 여러분의 기기를 벗어납니다.",
    "simple94.sections.2.link": "클라이언트 탐색",
    "simple94.sections.3.h": "AI 모델 선택을 위한 카탈로그",
    "simple94.sections.3.p.0": "Registry(레지스트리)는 AI 모델을 찾고 고르는 데 도움이 되는 공개 목록입니다. 각 모델이 할 수 있는 일, 라이선스, 필요한 하드웨어, 그리고 직접 실행하든 클라우드에서 실행하든 추정 비용을 알려 줍니다.",
    "simple94.sections.3.p.1": "Registry는 품질을 인증하거나 성능이나 비용 절감을 보장하지 않습니다. 출발점일 뿐이며, 커뮤니티의 의견을 받으며 성장하도록 만들어졌습니다. 도구를 비교하고 알맞은 것을 찾을 수 있도록 명확하고 실용적인 정보를 제공하는 것이 목표입니다.",
    "simple94.sections.3.link": "Registry 둘러보기",
    "simple94.sections.4.h": "당신의 AI를 위한 휴대용 홈",
    "simple94.sections.4.p.0": "엔키 기기는 지원되는 AI 모델을 스스로 실행하도록 설계된 작고 휴대할 수 있는 컴퓨터라는 구상입니다. 여러분의 AI를 위한 로컬 허브 역할을 하며, 모든 작업마다 인터넷에 계속 연결하지 않고도 휴대폰과 다른 스마트 기기에 연결됩니다.",
    "simple94.sections.4.p.1": "목표는 많은 작업을 로컬에서 처리해, 의무적인 클라우드 계정에서 벗어나게 해 주는 기기입니다. 설계는 개방형이어서 여러 회사가 호환되는 하드웨어를 만들 수 있게 됩니다. 이 기기는 아직 나오지 않았으며, 다른 컴퓨터와 마찬가지로 하드웨어, 전기, 유지 관리에 비용이 들 것입니다.",
    "simple94.sections.4.link": "장치 만나보기",
    "simple94.sections.5.h": "AI의 영향 이해하기",
    "simple94.sections.5.p.0": "엔키 연구소(Enki Institute)는 인공지능이 현실에 미치는 영향을 연구하고 보고하는 계획 중인 연구 기관입니다. 연구자들은 AI가 일자리, 문화, 경제를 어떻게 바꾸고 있는지 조사하고, 그 결과를 대중에게 공개적으로 공유할 것입니다.",
    "simple94.sections.5.p.1": "연구소는 검증된 진전이 일상 기기에 쓸 만큼 충분히 저렴하고 믿을 만해졌는지를 포함해 엔키의 바탕이 된 생각들도 검증하고, 무엇이 되고 무엇이 안 되는지 보고할 것입니다. 목표는 정책 결정자, 개발자, 시민이 기술과 그것이 우리 삶에서 차지할 자리에 대해 충분한 지식을 바탕으로 결정할 수 있게 하는 것입니다.",
    "simple94.sections.5.link": "연구소 방문하기",
    "simple94.status.h": "프로젝트 현황",
    "simple94.status.p.0": "선언문, 프로젝트 제안서, 시작용 모델 목록은 공개되어 있습니다. 프로토콜, 클라이언트, 휴대용 기기, 연구소는 아직 만들어서 검증해야 하는 구상입니다. '300'은 이러한 아이디어를 발전시킬 창립 그룹의 목표 인원이며, 현재 회원 수가 아닙니다. 회비는 없습니다.",
    "simple94.back": "Enki.ngo로 돌아가기",
    "simple94.read": "3분 읽기",
