    "r90.d5eb2b9d1296": "지능은 <span>모두</span>의 것입니다. 어디에나.",
    "r90.4dc023ed6f6d": "로컬 우선 AI를 위한 공공재 이니셔티브의 창립. 제안: 300명의 회원, 회비 없음, 좌석당 한 표. 법적 등록, 거버넌스 및 기술은 함께 구축해야 할 작업으로 남아 있습니다.",
    "r90.0b5f905b545a": "리스본 · 2026년 설립 · 미등록 — 의도적으로",
    "r90.b6747064b2a6": "프로그램",
